-- RSI pass 6 on the K5 harness model: the part master completed from the build's cited catalog, and a re-runnable key
-- fold for wire ends. Case ledger 13.12.2 step (c).
--
-- Measured 2026-10-14 (read-only): of the 884 K5 wire ends on live segments, 27 are keyed to a terminal part and 211 to a
-- crimp tool. The unkeyed part numbers are the build's main ones: SSC-N (179 ends), M39029/56-351 and /58-363 (58 + 58),
-- D-609-03 (53), 0460-202-16141 (38), the K1S positioner M22520/2-02 (179 tool keys). None is in catalog_parts (the part
-- master the harness keys point at, 13.12.2 step a); the ProWire scrape of 2026-05-11 that seeded its wiring rows missed
-- them. The build's own catalog (docs/wiring/calc-data/catalog/parts.yaml and tools.yaml) holds each with its source.
--
-- This pass:
--   1. Inserts the cited catalog entries absent from catalog_parts (by part number), generated by
--      docs/wiring/calc-data/catalog_parts_sql.py: 129 entries (open, retired and unsourced ones left out; tools only with a
--      part number); supplier page from the stored snapshot where one exists (66). No price, no stock, no manufacturer
--      claim (the table defaults manufacturer to 'LMC' and in_stock to true; both are set null here), no purchase state.
--   2. key_harness_wire_ends(vehicle_id): every part-number / catalog-key pair on wire_termination_specs (terminal, crimp
--      tool, seal, wedge, housing, heat shrink, label, boot), keyed where exactly one catalog row has that part number
--      (1,271 part numbers have more than one row; those wait for the catalog's dedupe); idempotent. Run for the K5.
BEGIN;
SET LOCAL statement_timeout='60s'; SET LOCAL lock_timeout='2s';

DO $guard$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'harness_endpoints' AND column_name = 'node_kind') THEN
    RAISE EXCEPTION 'net fold v2 (20261014153000) has not run';
  END IF;
  IF to_regprocedure('public.key_harness_wire_ends(uuid)') IS NOT NULL THEN
    RAISE EXCEPTION 'key_harness_wire_ends already exists';
  END IF;
END $guard$;

CREATE TEMP TABLE cat6 (part_number text PRIMARY KEY, name text NOT NULL, subcategory text, supplier text, supplier_url text, app jsonb NOT NULL) ON COMMIT DROP;
;

-- 1. The part master, completed.
SELECT c.part_number, c.name,
       'From the K5 build catalog (' || (c.app->>'source_file') || '); sources in application_data.',
       'wiring', c.subcategory, NULL, NULL, c.supplier_url, c.app
FROM cat6 c
WHERE NOT EXISTS (SELECT 1 FROM public.catalog_parts p WHERE p.part_number = c.part_number);

-- 2. The key fold.
CREATE FUNCTION public.key_harness_wire_ends(p_vehicle_id uuid) RETURNS integer
LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $fn$
DECLARE total int := 0; n int; pair text[];
BEGIN
  FOREACH pair SLICE 1 IN ARRAY ARRAY[
    ['terminal_contact_pn', 'terminal_contact_catalog_id'], ['crimp_tool_pn', 'crimp_tool_catalog_id'],
    ['pin_seal_pn', 'pin_seal_catalog_id'], ['wedge_lock_pn', 'wedge_lock_catalog_id'],
    ['connector_housing_pn', 'connector_housing_catalog_id'], ['heat_shrink_pn', 'heat_shrink_catalog_id'],
    ['label_pn', 'label_catalog_id'], ['boot_pn', 'boot_catalog_id']]
  LOOP
    EXECUTE format(
      'UPDATE public.wire_termination_specs t SET %2$I = c.id
         FROM (SELECT part_number, min(id::text)::uuid AS id FROM public.catalog_parts GROUP BY part_number HAVING count(*) = 1) c
        WHERE t.vehicle_id = $1 AND NOT coalesce(t.is_superseded, false) AND t.%2$I IS NULL AND c.part_number = t.%1$I',
      pair[1], pair[2]) USING p_vehicle_id;
    GET DIAGNOSTICS n = ROW_COUNT;
    total := total + n;
  END LOOP;
  RETURN total;
END
$fn$;
COMMENT ON FUNCTION public.key_harness_wire_ends(uuid) IS 'Key fold for stack SH: fills every catalog key on a vehicle''s live wire ends (terminal, crimp tool, seal, wedge, housing, heat shrink, label, boot) from its part number where exactly one catalog_parts row has that number; idempotent; returns the number of keys set. Run after catalog rows land.';
REVOKE ALL ON FUNCTION public.key_harness_wire_ends(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.key_harness_wire_ends(uuid) TO service_role;


-- Result.
DO $check$
DECLARE added int; keys int; term int; tool int; total int;
BEGIN
  SELECT count(*) INTO added FROM public.catalog_parts WHERE application_data->>'loaded_by' = 'rsi pass 6 (catalog_parts_sql.py)';
  keys := public.key_harness_wire_ends('e08bf694-970f-4cbe-8a74-8715158a0f2e');
  SELECT count(terminal_contact_catalog_id), count(crimp_tool_catalog_id), count(*) INTO term, tool, total
  FROM public.wire_termination_specs t
  WHERE t.vehicle_id = 'e08bf694-970f-4cbe-8a74-8715158a0f2e' AND NOT coalesce(t.is_superseded, false)
    AND EXISTS (SELECT 1 FROM public.harness_segments s WHERE NOT s.is_superseded AND t.id IN (s.from_termination_id, s.to_termination_id));
  RAISE NOTICE 'RSI pass 6: % catalog rows added; % keys set; K5 wire ends keyed to a terminal part % of %, to a crimp tool % of %',
    added, keys, term, total, tool, total;
END $check$;

COMMIT;
